'use client'

import { useState } from 'react'
import { useRouter } from 'next/navigation'
import Image from 'next/image'
import { getKit } from '@/lib/kit'
import { setSession, getSession } from '@/lib/session'

const FRIENDLY_ERRORS: Record<string, string> = {
  NotAllowedError: 'Cancelled — try again',
  InvalidStateError: 'Already registered — use Sign In instead',
  SecurityError: 'Requires HTTPS or localhost',
  NotSupportedError: 'Passkeys not supported in this browser',
  AbortError: 'Request was aborted',
}

function toFriendlyError(err: unknown): string {
  if (err instanceof Error) return FRIENDLY_ERRORS[err.name] ?? err.message
  return 'Unknown error'
}

export default function LandingPage() {
  const router = useRouter()
  const [createStatus, setCreateStatus] = useState<'idle' | 'pending' | 'error'>('idle')
  const [signInStatus, setSignInStatus] = useState<'idle' | 'pending' | 'error'>('idle')
  const [createError, setCreateError] = useState<string | null>(null)
  const [signInError, setSignInError] = useState<string | null>(null)

  async function handleCreateWallet() {
    setCreateStatus('pending')
    setCreateError(null)
    try {
      const kit = getKit()
      const { contractId, credentialId } = await kit.createWallet('SealPass', 'user')
      setSession({ contractId, credentialId })
      router.push('/app')
    } catch (err) {
      setCreateError(toFriendlyError(err))
      setCreateStatus('error')
    }
  }

  async function handleSignIn() {
    setSignInStatus('pending')
    setSignInError(null)
    try {
      const session = getSession()
      if (!session) {
        setSignInError('No wallet found — create one first')
        setSignInStatus('error')
        return
      }
      const kit = getKit()
      await kit.connectWallet({ contractId: session.contractId, credentialId: session.credentialId })
      router.push('/app')
    } catch (err) {
      setSignInError(toFriendlyError(err))
      setSignInStatus('error')
    }
  }

  return (
    <div className="min-h-screen flex flex-col items-center justify-center px-4 py-12" style={{ background: '#f0f4ff' }}>
      <div className="flex flex-col items-center gap-8 w-full max-w-xl">
        {/* Logo */}
        <Image src="/logo2.jpeg" alt="SealPass Smart Wallet" width={400} height={150} className="rounded-2xl shadow-md" priority />

        {/* Tagline */}
        <div className="text-center">
          <p className="text-lg font-semibold mb-1" style={{ color: '#1a2e5c' }}>
            Your Stellar wallet, secured by passkey
          </p>
          <p className="text-sm" style={{ color: '#5472a0' }}>
            No seed phrases. No complexity.
          </p>
        </div>

        {/* CTA Cards */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4 w-full">
          {/* Create Wallet */}
          <div className="bg-white rounded-2xl p-6 flex flex-col gap-4 shadow-sm border border-slate-200">
            <div>
              <h2 className="text-base font-bold mb-1" style={{ color: '#1a2e5c' }}>Create Wallet</h2>
              <p className="text-sm" style={{ color: '#5472a0' }}>
                Register a new Stellar smart account secured by your device passkey.
              </p>
            </div>
            {createError && (
              <p className="text-sm text-red-600 bg-red-50 rounded-lg px-3 py-2 border border-red-100">{createError}</p>
            )}
            <button
              onClick={handleCreateWallet}
              disabled={createStatus === 'pending'}
              className="w-full py-2.5 rounded-xl font-bold text-white disabled:opacity-50 disabled:cursor-not-allowed transition-all shadow-sm"
              style={{ background: '#2563eb' }}
            >
              {createStatus === 'pending' ? 'Creating…' : 'Create Wallet'}
            </button>
          </div>

          {/* Sign In */}
          <div className="bg-white rounded-2xl p-6 flex flex-col gap-4 shadow-sm border border-slate-200">
            <div>
              <h2 className="text-base font-bold mb-1" style={{ color: '#1a2e5c' }}>Sign In</h2>
              <p className="text-sm" style={{ color: '#5472a0' }}>
                Authenticate with your existing passkey to access your wallet.
              </p>
            </div>
            {signInError && (
              <p className="text-sm text-red-600 bg-red-50 rounded-lg px-3 py-2 border border-red-100">{signInError}</p>
            )}
            <button
              onClick={handleSignIn}
              disabled={signInStatus === 'pending'}
              className="w-full py-2.5 rounded-xl font-bold border-2 disabled:opacity-50 disabled:cursor-not-allowed transition-all"
              style={{ color: '#2563eb', borderColor: '#2563eb', background: 'transparent' }}
            >
              {signInStatus === 'pending' ? 'Signing in…' : 'Sign In'}
            </button>
          </div>
        </div>

        {/* Feature bullets */}
        <div className="flex flex-col md:flex-row gap-8 text-center pt-2">
          {[
            { icon: '🛡️', title: 'Phishing-resistant', sub: 'Cryptographically bound to this domain' },
            { icon: '🔄', title: 'Synced across devices', sub: 'iCloud Keychain & Google Password Manager' },
            { icon: '✨', title: 'No seed phrases', sub: 'Your passkey IS your key' },
          ].map(({ icon, title, sub }) => (
            <div key={title} className="flex flex-col items-center gap-1.5">
              <span className="text-2xl">{icon}</span>
              <span className="text-sm font-semibold" style={{ color: '#1a2e5c' }}>{title}</span>
              <span className="text-xs" style={{ color: '#94a3b8' }}>{sub}</span>
            </div>
          ))}
        </div>

        <p className="text-xs" style={{ color: '#94a3b8' }}>Built on the Stellar Network · Testnet</p>
      </div>
    </div>
  )
}
